// Extrae el mensaje entrante del payload de WhatsApp Cloud API.
// Devuelve [] para eventos sin mensaje (p. ej. estados "sent"/"delivered"/"read").
const body = $input.first().json.body || {};
const value = body.entry?.[0]?.changes?.[0]?.value;
const msg = value?.messages?.[0];
if (!msg) return [];

// Deduplicación: Meta puede reenviar el mismo webhook.
const store = $getWorkflowStaticData('global');
store.processed = store.processed || [];
if (store.processed.includes(msg.id)) return [];
store.processed.push(msg.id);
store.processed = store.processed.slice(-500);

const contactName = value.contacts?.[0]?.profile?.name || '';
let text = '';
let buttonId = '';
let needsAI = true;
let directReply = '';

switch (msg.type) {
  case 'text':
    text = msg.text?.body || '';
    break;
  case 'interactive':
    // Respuesta a botones (p. ej. el consentimiento: consent_si / consent_no) o a una lista.
    buttonId = msg.interactive?.button_reply?.id || msg.interactive?.list_reply?.id || '';
    text = msg.interactive?.button_reply?.title || msg.interactive?.list_reply?.title || '';
    break;
  case 'button':
    buttonId = msg.button?.payload || '';
    text = msg.button?.text || '';
    break;
  default:
    // Audio, imagen, documento, ubicación, etc.: se avisa al modelo para que responda según el system prompt.
    text = `[El usuario envió un mensaje de tipo "${msg.type}" que el asistente no puede leer.]`;
}

if (!text.trim()) {
  needsAI = false;
  directReply = 'Disculpe, no pude leer su mensaje. ¿Podría escribirnos su consulta en texto, por favor?';
}

return [{
  json: {
    from: msg.from,
    messageId: msg.id,
    contactName,
    phoneNumberId: value.metadata?.phone_number_id,
    text: text.slice(0, 4000),
    buttonId,
    needsAI,
    directReply,
  },
}];

// Arma la solicitud al LLM (Ollama o Anthropic, según LLM_PROVIDER) con el historial de la conversación.
const fs = require('fs');
// Se lee la salida de "Estado de la cita" (no $input): los nodos intermedios no deben alterar los datos.
const input = $('Estado de la cita').first().json;

const provider = ($env.LLM_PROVIDER || 'ollama').trim().toLowerCase();
if (!['ollama', 'anthropic'].includes(provider)) {
  throw new Error(`LLM_PROVIDER no válido: "${provider}". Use "ollama" o "anthropic".`);
}

// El system prompt (incluido su "Recordatorio final") vive solo en system_prompt.md.
const promptPath = $env.SYSTEM_PROMPT_PATH || '/data/system_prompt.md';
let systemPrompt;
try {
  systemPrompt = fs.readFileSync(promptPath, 'utf8');
} catch (e) {
  throw new Error(`No se pudo leer el system prompt en ${promptPath}: ${e.message}`);
}
// Estado del consentimiento, al final del recordatorio. Va después del texto fijo para no romper la
// caché del prompt (Ollama reutiliza el prefijo idéntico; Claude cachea el primer bloque).
// Si hay una solicitud de cita en curso o registrada, se agrega en otra línea (ver "Estado de la cita").
const consentLine = `Consentimiento: ${input.consentStatus || 'pendiente'}` + (input.citaLine ? `
${input.citaLine}` : '');

// Memoria simple en static data del workflow (solo persiste en ejecuciones de producción).
const store = $getWorkflowStaticData('global');
store.conversations = store.conversations || {};
const maxTurns = parseInt($env.CONVERSATION_MAX_MESSAGES || '20', 10);
const ttlMs = parseInt($env.CONVERSATION_TTL_HOURS || '24', 10) * 3600 * 1000;

let convo = store.conversations[input.from];
if (!convo || Date.now() - convo.updatedAt > ttlMs) {
  convo = { messages: [], updatedAt: Date.now() };
}

const now = new Date().toLocaleString('es-PE', {
  timeZone: $env.BUSINESS_TIMEZONE || 'America/Lima',
  dateStyle: 'full',
  timeStyle: 'short',
});
const nameNote = input.contactName ? ` | Nombre de perfil en WhatsApp: ${input.contactName}` : '';
const currentTurn = `[Contexto del sistema: fecha y hora actual: ${now}${nameNote}]\n\n${input.text}`;
const messages = [...convo.messages, { role: 'user', content: currentTurn }];

let llmBody;
if (provider === 'anthropic') {
  llmBody = {
    model: $env.ANTHROPIC_MODEL || 'claude-sonnet-5-5',
    max_tokens: parseInt($env.ANTHROPIC_MAX_TOKENS || '8000', 10),
    thinking: { type: 'adaptive' },
    output_config: { effort: $env.ANTHROPIC_EFFORT || 'low' },
    // Si un clasificador de seguridad rechaza la solicitud, la API la reintenta en el modelo recomendado.
    fallbacks: 'default',
    system: [
      { type: 'text', text: systemPrompt, cache_control: { type: 'ephemeral' } },
      { type: 'text', text: consentLine },
    ],
    messages,
  };
} else {
  llmBody = {
    model: $env.OLLAMA_MODEL || 'llama3:latest',
    stream: false,
    keep_alive: $env.OLLAMA_KEEP_ALIVE || '30m',
    options: {
      temperature: parseFloat($env.OLLAMA_TEMPERATURE || '0.3'),
      num_ctx: parseInt($env.OLLAMA_NUM_CTX || '8192', 10),
      num_predict: parseInt($env.OLLAMA_NUM_PREDICT || '200', 10), // 2 oraciones + bloque <cita> ≈ 150 tokens
    },
    messages: [{ role: 'system', content: `${systemPrompt.trimEnd()}\n\n${consentLine}\n` }, ...messages],
  };
}

return [{ json: { ...input, provider, llmBody, history: convo.messages, maxTurns } }];

// Procesa la respuesta del LLM (Ollama o Anthropic), extrae el bloque <cita>, aplica el filtro de
// consentimiento y actualiza la memoria.
const res = $input.first().json;
const ctx = $('Preparar solicitud LLM').first().json;

const FALLBACK = 'Disculpe, en este momento no puedo procesar su mensaje. Un miembro de nuestro equipo le contactará en horario de atención. Gracias por escribir a JS CONSULTORES Y ABOGADOS.';
const REFUSAL = 'Disculpe, no puedo ayudarle con esa solicitud por este medio. Si lo desea, puedo coordinar una consulta con el equipo del estudio.';

let reply = '';
let ok = false;

if (res.error) {
  // LLM caído, modelo no descargado, clave inválida o tiempo de espera agotado.
  reply = FALLBACK;
} else if (ctx.provider === 'anthropic') {
  if (res.stop_reason === 'refusal') {
    reply = REFUSAL;
  } else if (Array.isArray(res.content)) {
    // Solo bloques de texto: la respuesta puede incluir bloques "thinking" que no se envían.
    reply = res.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
    ok = true;
  }
} else if (res.message && typeof res.message.content === 'string') {
  reply = res.message.content;
  ok = true;
}

reply = reply.replace(/<think>[\s\S]*?<\/think>/g, '').trim(); // por si se usa un modelo con razonamiento visible
if (!reply) { reply = FALLBACK; ok = false; }

// Extraer la solicitud de cita (respaldo: el registro lo lleva "Estado de la cita"), tolerando bloques de código alrededor. Si el modelo emitió varios
// bloques se usa el último válido, y se retiran todos del mensaje visible.
const CITA_RE = /(```[a-z]*\s*)?<cita>([\s\S]*?)<\/cita>(\s*```)?/gi;
const parseCita = (raw) => {
  raw = raw.trim();
  try { return JSON.parse(raw); } catch (e) {}
  const obj = raw.match(/\{[\s\S]*\}/);
  try { return obj ? JSON.parse(obj[0]) : { raw }; } catch (e) { return { raw }; }
};
let appointment = null;
for (const m of reply.matchAll(CITA_RE)) {
  const parsed = parseCita(m[2]);
  if (!appointment || !parsed.raw || appointment.raw) appointment = parsed;
}
if (appointment) {
  reply = reply.replace(CITA_RE, '').trim();
}
// Etiquetas <cita> sueltas o sin cerrar: no mostrarlas al usuario.
reply = reply.replace(/<\/?cita>[\s\S]*$/i, '').trim();
if (!reply && appointment) {
  reply = 'Gracias, he registrado su solicitud. Un miembro de nuestro equipo le confirmará la cita en horario de atención.';
} else if (!reply) {
  reply = FALLBACK;
  ok = false;
}

if (reply.length > 4000) reply = reply.slice(0, 3990) + '…';

const consented = ctx.consentStatus === 'otorgado';
let waMessage = { type: 'text', text: { preview_url: false, body: reply } };

// Filtro de salida (Ley N.° 29733): sin consentimiento otorgado, si la IA pide nombre, correo, DNI,
// teléfono o dirección, se reemplaza su respuesta por el mensaje de consentimiento con botones.
const DATA_WORD = /(nombre|apellido|correo|e-?mail|\bdni\b|documento de identidad|tel[eé]fono|celular|n[uú]mero de contacto|direcci[oó]n|domicilio)/i;
const REQUEST = /(ind[ií]queme|ind[ií]quenos|ind[ií]came|me (indica|brinda|proporciona|comparte|da|facilita|dice|deja|escribe|env[ií]a)|br[ií]ndeme|proporci[oó]neme|comp[aá]rtame|facil[ií]teme|d[eé]jeme|d[eé]jenos|env[ií]eme|escr[ií]bame|podr[ií]a (darme|indicarme|brindarme|compartir|proporcionar|dejarnos|enviarme|facilitarme)|necesit(o|amos|aremos)|requerimos|cu[aá]l es su|a nombre de qui[eé]n|puede dejar)/i;
const asksPersonalData = (text) => text.split(/(?<=[.?!\n])\s+/).some((s) =>
  DATA_WORD.test(s) && (REQUEST.test(s) || (/\bsus?\b/i.test(s) && s.includes('?'))));
let blockedByConsent = false;
if (ok && !consented && asksPersonalData(reply)) {
  blockedByConsent = true;
  reply = ctx.consentText;
  waMessage = ctx.consentPrompt;
  const store = $getWorkflowStaticData('global');
  store.consents = store.consents || {};
  store.consents[ctx.from] = { ...(store.consents[ctx.from] || { estado: 'pendiente' }), prompted: true };
}

if (ok) {
  const store = $getWorkflowStaticData('global');
  store.conversations = store.conversations || {};
  const msgs = [
    ...ctx.history,
    { role: 'user', content: ctx.text },
    { role: 'assistant', content: reply },
  ];
  let trimmed = msgs.slice(-ctx.maxTurns);
  if (trimmed.length && trimmed[0].role !== 'user') trimmed = trimmed.slice(1);
  store.conversations[ctx.from] = { messages: trimmed, updatedAt: Date.now() };
}

// Sin consentimiento otorgado no se registra ni se notifica ninguna cita.
const validAppointment = !!appointment && !appointment.raw && consented;

const u = res.usage || {};
return [{
  json: {
    from: ctx.from,
    phoneNumberId: ctx.phoneNumberId,
    reply,
    waMessage,
    blockedByConsent,
    consentStatus: ctx.consentStatus,
    policyVersion: ctx.policyVersion,
    citaPending: ctx.citaPending || '',
    appointment: consented ? appointment : null,
    hasAppointment: validAppointment,
    provider: ctx.provider,
    usage: {
      input_tokens: u.input_tokens ?? res.prompt_eval_count ?? null,
      output_tokens: u.output_tokens ?? res.eval_count ?? null,
      total_ms: res.total_duration ? Math.round(res.total_duration / 1e6) : null,
    },
  },
}];

// Puerta de consentimiento (Ley N.° 29733), determinista: decide SIN la IA cuándo pedir, registrar o
// respetar el consentimiento. Devuelve action "llm" (sigue a la IA) o "reply" (mensaje fijo en waMessage).
const input = $input.first().json;
const from = input.from;
const store = $getWorkflowStaticData('global');
store.conversations = store.conversations || {};
store.consents = store.consents || {};
const policyVersion = ($env.POLICY_VERSION || '').trim() || 'sin-version';
const maxTurns = parseInt($env.CONVERSATION_MAX_MESSAGES || '20', 10);
const ttlMs = parseInt($env.CONVERSATION_TTL_HOURS || '24', 10) * 3600 * 1000;

// Texto fijo de crm/ARQUITECTURA.md §6 (igual al de system_prompt.md).
const CONSENT_TEXT = 'Para gestionar su cita necesitamos usar algunos datos personales (nombre, horario preferido y, opcionalmente, su correo), conforme a la Ley N.° 29733. Puede revisar nuestra política en construccionesyedificacionesjys.com/terminos.html#privacidad. ¿Nos autoriza?';
const ACCEPTED = 'Gracias, hemos registrado su autorización. ¿Me indica su nombre completo, por favor?';
const REJECTED = 'Entendido, no usaremos sus datos personales; puedo darle información general o puede comunicarse directamente al WhatsApp 956 771 681, al teléfono 993 793 224 o al correo Ejuridicojys@gmail.com. Si cambia de opinión, escriba *Acepto*.';

const textMessage = (body) => ({ type: 'text', text: { preview_url: false, body } });
const consentPrompt = {
  type: 'interactive',
  interactive: {
    type: 'button',
    body: { text: CONSENT_TEXT },
    action: { buttons: [
      { type: 'reply', reply: { id: 'consent_si', title: 'Acepto' } },
      { type: 'reply', reply: { id: 'consent_no', title: 'No acepto' } },
    ] },
  },
};

// Estado vigente: un "otorgado" de una versión anterior de la política vuelve a "pendiente".
const consentOf = () => {
  const c = store.consents[from];
  if (!c) return { estado: 'pendiente' };
  if (c.estado === 'otorgado' && c.version !== policyVersion) return { ...c, estado: 'pendiente' };
  return c;
};

// Guarda el intercambio en el historial, para que la IA conozca el contexto en el siguiente turno.
const remember = (userText, assistantText) => {
  let convo = store.conversations[from];
  if (!convo || Date.now() - convo.updatedAt > ttlMs) convo = { messages: [] };
  let msgs = [...convo.messages, { role: 'user', content: userText }, { role: 'assistant', content: assistantText }].slice(-maxTurns);
  if (msgs.length && msgs[0].role !== 'user') msgs = msgs.slice(1);
  store.conversations[from] = { messages: msgs, updatedAt: Date.now() };
};

const out = (extra) => [{ json: {
  from,
  messageId: input.messageId,
  contactName: input.contactName,
  phoneNumberId: input.phoneNumberId,
  text: input.text,
  consentStatus: consentOf().estado,
  policyVersion,
  consentText: CONSENT_TEXT,
  consentPrompt,
  consentEvent: '',
  ...extra,
} }];
const reply = (waMessage, visible, extra = {}) => out({ action: 'reply', waMessage, reply: visible, ...extra });

if (!input.needsAI) return reply(textMessage(input.directReply), input.directReply);

// Solo para pruebas: "/reiniciar" desde un número de TEST_NUMBERS borra su historial, su consentimiento
// el control de citas y la solicitud en curso. Para cualquier otro número es un mensaje normal.
const digits = (s) => String(s || '').replace(/\D/g, '');
const testNumbers = String($env.TEST_NUMBERS || '').split(',').map(digits).filter(Boolean);
if (String(input.text).trim().toLowerCase() === '/reiniciar' && testNumbers.includes(digits(from))) {
  delete store.conversations[from];
  delete store.consents[from];
  if (store.citas) delete store.citas[from];
  if (store.citaFlow) delete store.citaFlow[from];
  return reply(textMessage('Conversación reiniciada.'), 'Conversación reiniciada.');
}

const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9@ ]+/g, ' ').replace(/\s+/g, ' ').trim();
const t = norm(input.text);
const current = consentOf();

// 1) Respuesta al consentimiento: botones o, si se escribe, solo frases inequívocas.
const YES = ['acepto', 'si acepto', 'si, acepto', 'lo acepto', 'si lo acepto', 'autorizo', 'si autorizo', 'acepto gracias'];
const NO = ['no acepto', 'no lo acepto', 'no autorizo', 'no lo autorizo', 'no acepto gracias'];
let decision = null;
if (input.buttonId === 'consent_si') decision = 'otorgado';
else if (input.buttonId === 'consent_no') decision = 'rechazado';
else if (YES.includes(t)) decision = 'otorgado';
else if (NO.includes(t)) decision = 'rechazado';
else if (current.prompted && ['si', 'ok', 'de acuerdo', 'claro', 'si claro', 'si por favor'].includes(t)) decision = 'otorgado';
else if (current.prompted && t === 'no') decision = 'rechazado';

// Un "acepto" escrito cuando ya está otorgado (y no se acaba de preguntar) se deja a la IA.
if (decision && !(decision === current.estado && !input.buttonId && !current.prompted)) {
  store.consents[from] = {
    estado: decision,
    fecha: new Date().toISOString(),
    version: policyVersion,
    canal: input.buttonId ? 'whatsapp_botones' : 'whatsapp_texto',
    prompted: false,
  };
  const msg = decision === 'otorgado' ? ACCEPTED : REJECTED;
  remember(input.text, msg);
  return reply(textMessage(msg), msg, { consentEvent: decision });
}

// 2) Sin consentimiento otorgado: si hay intención de cita o de dar datos, se pide el consentimiento
//    con botones y NO se llama a la IA.
const INTENT = /\b(citas?|agendar|agendo|agenda|agendame|programar|reservar|consultas?|reunion|reunirme|reunirnos|abogad[oa]s?|doctora|asesor|asesoria|hablar con|comunicarme con|contactar|contactenme|llamenme|me llamo|mi nombre|mi correo|mi dni|mi telefono|mi celular|mi numero|mi direccion|separar|visita|visitar)\b/;
const EMAIL = /[^\s@]+@[^\s@]+\.[a-z]{2,}/i;
const LONG_NUMBER = /(\d[\s.-]?){8,}/; // DNI o teléfono
const hasData = EMAIL.test(input.text) || LONG_NUMBER.test(input.text) || /\b(me llamo|mi nombre es)\b/.test(t);
if (current.estado !== 'otorgado' && (INTENT.test(t) || hasData)) {
  store.consents[from] = { ...(store.consents[from] || { estado: 'pendiente' }), prompted: true };
  // Minimización: si el mensaje ya traía datos personales, no se guardan antes del consentimiento.
  remember(hasData ? '[Mensaje con datos personales omitido hasta obtener el consentimiento]' : input.text, CONSENT_TEXT);
  return reply(consentPrompt, CONSENT_TEXT);
}

// 3) Todo lo demás va a la IA, que recibe el estado del consentimiento.
return out({ action: 'llm' });

// Último paso antes de responder (todos los mensajes pasan por aquí). Si hay una solicitud de cita, la
// guarda CIFRADA (AES-256-GCM) en CITAS_FILE_PATH (por defecto /data/datos/citas.jsonl.enc, carpeta
// ./datos montada en docker-compose), una línea por cita, y ajusta la respuesta según el resultado:
//   - la cita armada por "Estado de la cita" (origen "flujo") solo se confirma si se guardó;
//   - el bloque <cita> de la IA (origen "ia") queda como respaldo;
//   - si la IA dice que registró la solicitud pero no se guardó nada, no se le dice eso al usuario.
// Formato de cada línea: "v1." + base64(iv de 12 bytes | texto cifrado | etiqueta de 16 bytes),
// con AAD "jys-citas-v1". Se lee con herramientas/ver_citas.py.
const crypto = require('crypto');
const fs = require('fs');
const input = $input.first().json;
const from = input.from;
const store = $getWorkflowStaticData('global');
store.citas = store.citas || {};
store.citaFlow = store.citaFlow || {};
store.conversations = store.conversations || {};
const ttlMs = parseInt($env.CONVERSATION_TTL_HOURS || '24', 10) * 3600 * 1000;

const KEYS = ['nombre', 'area', 'resumen', 'tipo_cliente', 'modalidad', 'preferencia_horaria', 'correo', 'urgente', 'contacto_humano', 'estado'];
const NO_CITA = 'Aún no he registrado su solicitud de cita.';
// Frases con las que la IA da por registrada (o confirmada) una cita.
const CLAIM = /(registrad[ao]|he registrado|hemos registrado|registr[eé] su|qued[oó] (agendad|programad|reservad|confirmad)|est[aá] (agendad|programad|reservad|confirmad)|cita (agendada|programada|reservada|confirmada))/i;
const claimsCita = (s) => s.split(/(?<=[.!?\n])\s+/).some((x) => CLAIM.test(x) && /(cita|solicitud|reserv|agend)/i.test(x));
const textMessage = (body) => ({ type: 'text', text: { preview_url: false, body } });

// Copia: al final se reasigna a static data para que n8n detecte el cambio.
const live = store.citaFlow[from] && Date.now() - store.citaFlow[from].updatedAt <= ttlMs ? store.citaFlow[from] : null;
const flow = live ? { ...live, datos: { ...live.datos } } : null;
const fromLLM = !!input.provider; // la respuesta viene de "Procesar respuesta"

// Cita a guardar: la del flujo, o la del bloque <cita> de la IA si el flujo no registró ya una.
let source = '';
let raw = null;
if (input.citaToSave) { source = 'flujo'; raw = input.citaToSave; }
else if (input.hasAppointment && input.appointment && !(flow && flow.estado === 'registrada')) { source = 'ia'; raw = input.appointment; }
const cita = raw ? Object.fromEntries(KEYS.map((k) => [k, raw[k] ?? ''])) : null;
const consent = store.consents?.[from] || {};

let track = store.citas[from];
if (!track || Date.now() - track.updatedAt > ttlMs) track = { hash: '', notified: false };
let saved = false;
let duplicate = false;
let error = '';
let notify = false;

if (cita) {
  // Mismo contenido que la última línea guardada para este número: no se repite.
  const hash = crypto.createHash('sha256').update(from + JSON.stringify(cita)).digest('hex');
  duplicate = hash === track.hash;
  if (!duplicate) {
    const keyHex = ($env.CITAS_FILE_KEY || '').trim();
    if (!/^[0-9a-fA-F]{64}$/.test(keyHex)) {
      error = 'CITAS_FILE_KEY no está configurada o no tiene 64 caracteres hexadecimales (32 bytes).';
    } else {
      try {
        const record = {
          registrado: new Date().toISOString(),
          telefono: from,
          linea: input.phoneNumberId || '',
          origen: source,
          consentimiento: { estado: consent.estado || input.consentStatus, version: consent.version || input.policyVersion, fecha: consent.fecha || '' },
          ...cita,
        };
        const iv = crypto.randomBytes(12);
        const cipher = crypto.createCipheriv('aes-256-gcm', Buffer.from(keyHex, 'hex'), iv);
        cipher.setAAD(Buffer.from('jys-citas-v1'));
        const ct = Buffer.concat([cipher.update(JSON.stringify(record), 'utf8'), cipher.final()]);
        const line = 'v1.' + Buffer.concat([iv, ct, cipher.getAuthTag()]).toString('base64');
        const file = $env.CITAS_FILE_PATH || '/data/datos/citas.jsonl.enc';
        try {
          fs.mkdirSync(file.replace(/[\\/][^\\/]*$/, '') || '.', { recursive: true }); // solo fs y crypto están permitidos
          fs.appendFileSync(file, line + '\n', { mode: 0o600 });
          saved = true;
        } catch (e) {
          error = `No se pudo escribir ${file}: ${e.code || e.message}`;
        }
      } catch (e) {
        error = `No se pudo cifrar la cita: ${e.message}`;
      }
    }
    // Sin datos personales en el log: solo el motivo.
    if (error) console.error(`[Guardar cita cifrada] ${error}`);
  }
  // Aviso al estudio una sola vez por conversación, cuando la solicitud está completa, es urgente o
  // pide atención humana (también si no se pudo guardar, para que el estudio lo sepa).
  const notifiable = cita.estado === 'completa' || cita.contacto_humano === true || cita.urgente === true;
  notify = !duplicate && notifiable && !track.notified;
  store.citas[from] = { hash: saved || duplicate ? hash : track.hash, notified: track.notified || notify, updatedAt: Date.now() };
}
const ok = saved || duplicate;

// Estado de la solicitud según el resultado.
if (source === 'flujo' && flow) {
  flow.estado = ok ? 'registrada' : 'fallida';
  flow.updatedAt = Date.now();
}
if (source === 'ia' && flow && flow.estado === 'en_curso') {
  // Lo que la IA recogió completa los datos que falten en el flujo, para no volver a pedirlos.
  const d = flow.datos;
  if (!d.nombre && cita.nombre) d.nombre = cita.nombre;
  if (!d.tema && cita.resumen) d.tema = cita.resumen;
  if (!d.modalidad && ['presencial', 'virtual'].includes(cita.modalidad)) d.modalidad = cita.modalidad;
  if (!d.horario && cita.preferencia_horaria) d.horario = cita.preferencia_horaria;
  if (!d.correo && cita.correo) { d.correo = cita.correo; flow.correoResuelto = true; }
  if (ok && cita.estado === 'completa') flow.estado = 'registrada';
  flow.updatedAt = Date.now();
}
if (flow && source) store.citaFlow[from] = flow;

// Respuesta final.
let reply = input.reply || '';
let waMessage = input.waMessage || textMessage(reply);
const original = reply;
if (source === 'flujo' && !ok) {
  reply = input.citaReplyFail || 'Disculpe, por un problema técnico no pude registrar su solicitud de cita.';
} else if (fromLLM && !input.blockedByConsent) {
  const registered = ok || (flow && flow.estado === 'registrada');
  if (claimsCita(reply) && !registered) {
    // La IA dice que registró la solicitud, pero no se guardó nada.
    reply = flow && flow.estado === 'en_curso' && input.citaPending
      ? `${NO_CITA} ${input.citaPending}`
      : `${NO_CITA} Si desea registrarla, escríbame *Quiero una cita*.`;
  } else if (flow && flow.estado === 'en_curso' && input.citaPending && !reply.trimEnd().endsWith('?')) {
    // La IA respondió una duda en medio de la solicitud: se vuelve a pedir el dato pendiente.
    reply = `${reply}\n\n${input.citaPending}`;
  }
}
if (reply !== original) {
  waMessage = textMessage(reply);
  // El historial debe reflejar lo que realmente se envió.
  const conv = store.conversations[from];
  const msgs = conv?.messages || [];
  const last = msgs[msgs.length - 1];
  if (last && last.role === 'assistant' && last.content === original) {
    store.conversations[from] = { ...conv, messages: [...msgs.slice(0, -1), { role: 'assistant', content: reply }] };
  }
}

const notifyNumber = ($env.FIRM_NOTIFY_WHATSAPP || '').replace(/\D/g, '');
const area = cita?.area || 'sin indicar';
const modalidad = cita?.modalidad || 'por_definir';
const flags = cita ? [cita.urgente === true ? 'URGENTE' : '', cita.contacto_humano === true ? 'pide hablar con una persona' : ''].filter(Boolean).join(', ') : '';
// Sin datos sensibles: ni nombre, ni teléfono, ni resumen del caso.
const notice = `Nueva solicitud de cita – área: ${area} – modalidad: ${modalidad}${flags ? ` – ${flags}` : ''}. Revise el registro.`
  + (ok ? '' : ' (ATENCIÓN: no se pudo guardar en el registro cifrado; revise los logs de n8n.)');

return [{
  json: {
    from,
    phoneNumberId: input.phoneNumberId,
    reply,
    waMessage,
    appointment: cita,
    origen: source,
    saved,
    duplicate,
    error,
    notifyWhatsApp: notify && notifyNumber.length >= 8,
    notifyWebhook: notify && !!($env.FIRM_NOTIFICATION_WEBHOOK_URL || '').trim(),
    notifyTo: notifyNumber,
    notice,
  },
}];

// Estado de la solicitud de cita, llevado por n8n y no por la IA (el bloque <cita> del modelo queda
// como respaldo). Guarda por número, en static data, el dato que se está pidiendo y los datos recogidos.
// Con consentimiento otorgado hace las preguntas fijas (un dato por mensaje) y, cuando tiene nombre,
// tema, modalidad y día/horario (y el correo opcional quedó resuelto), arma la cita para
// "Guardar cita cifrada", que la guarda y confirma al usuario solo si se guardó.
const input = $input.first().json;
const from = input.from;
const store = $getWorkflowStaticData('global');
store.citaFlow = store.citaFlow || {};
store.conversations = store.conversations || {};
const ttlMs = parseInt($env.CONVERSATION_TTL_HOURS || '24', 10) * 3600 * 1000;
const maxTurns = parseInt($env.CONVERSATION_MAX_MESSAGES || '20', 10);

const FIELDS = ['nombre', 'tema', 'modalidad', 'horario', 'correo'];
const LABELS = { nombre: 'nombre completo', tema: 'tema de la consulta', modalidad: 'modalidad', horario: 'día y horario', correo: 'correo (opcional)' };
const QUESTIONS = {
  nombre: '¿Me indica su nombre completo, por favor?',
  tema: '¿Podría contarme en una frase el tema de su consulta?',
  modalidad: '¿Prefiere una cita presencial en nuestra oficina o virtual?',
  horario: '¿Qué día y en qué horario le acomodaría, de lunes a viernes entre 9:00 a. m. y 6:00 p. m.?',
  correo: 'Si lo desea, puede dejarnos un correo para enviarle la confirmación; ¿me lo indica o prefiere continuar sin correo?',
};
// Cada respuesta fija tiene como máximo 2 oraciones y una sola pregunta (como pide system_prompt.md).
const BUTTONS = {
  modalidad: [['cita_presencial', 'Presencial'], ['cita_virtual', 'Virtual']],
  correo: [['cita_sin_correo', 'Sin correo']],
};
const ACK = { nombre: 'Gracias. ', tema: 'Entendido. ', modalidad: 'Perfecto. ', horario: 'Anotado. ', correo: 'Gracias. ' };
const RETRY = 'Disculpe, no le entendí. ';
const ACCEPTED_PREFIX = 'Gracias, hemos registrado su autorización. ';
const CANCELLED = 'Entendido, dejé sin efecto la solicitud de cita. ¿Puedo ayudarle en algo más?';
const NOT_SAVED = 'Disculpe, por un problema técnico no pude registrar su solicitud de cita. Por favor, escríbanos al WhatsApp 956 771 681 o llámenos al 993 793 224 para coordinarla.';

const textMessage = (body) => ({ type: 'text', text: { preview_url: false, body } });
const ask = (field, prefix = '') => {
  const body = `${prefix}${QUESTIONS[field]}`;
  if (!BUTTONS[field]) return { waMessage: textMessage(body), reply: body };
  return {
    waMessage: { type: 'interactive', interactive: { type: 'button', body: { text: body }, action: {
      buttons: BUTTONS[field].map(([id, title]) => ({ type: 'reply', reply: { id, title } })),
    } } },
    reply: body,
  };
};

const norm = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '')
  .replace(/[^a-z0-9@ ]+/g, ' ').replace(/\s+/g, ' ').trim();
const text = String(input.text || '').trim();
const t = norm(text);

// Historial: los turnos con respuesta fija también se guardan, para que la IA conozca el contexto.
const history = () => {
  const c = store.conversations[from];
  return c && Date.now() - c.updatedAt <= ttlMs ? c.messages : [];
};
const remember = (userText, assistantText) => {
  let msgs = [...history(), { role: 'user', content: userText }, { role: 'assistant', content: assistantText }].slice(-maxTurns);
  if (msgs.length && msgs[0].role !== 'user') msgs = msgs.slice(1);
  store.conversations[from] = { messages: msgs, updatedAt: Date.now() };
};
const replaceLastAssistant = (oldText, newText) => {
  const msgs = history();
  const last = msgs[msgs.length - 1];
  if (last && last.role === 'assistant' && last.content === oldText) {
    // Se reasigna (no solo se modifica) para que n8n detecte el cambio en static data.
    store.conversations[from] = { messages: [...msgs.slice(0, -1), { role: 'assistant', content: newText }], updatedAt: Date.now() };
  }
};

const live = (f) => (f && Date.now() - f.updatedAt <= ttlMs ? f : null);
const missing = (f) => FIELDS.find((k) => (k === 'correo' ? !f.correoResuelto : !f.datos[k])) || null;
// Una nueva solicitud conserva el nombre y el correo de una anterior: no se vuelven a pedir.
const start = (prev) => ({
  estado: 'en_curso',
  asked: '',
  datos: { nombre: prev?.datos?.nombre || '', tema: '', modalidad: '', horario: '', correo: prev?.datos?.correo || '' },
  correoResuelto: !!prev?.correoResuelto,
  urgente: false,
  contactoHumano: false,
  updatedAt: Date.now(),
});
const save = (f) => { store.citaFlow[from] = { ...f, datos: { ...f.datos }, updatedAt: Date.now() }; };
const pendingOf = (f) => { const m = f && f.estado === 'en_curso' ? missing(f) : null; return m ? QUESTIONS[m] : ''; };

const out = (extra) => [{ json: { ...input, citaLine: '', citaPending: '', citaToSave: null, citaReplyFail: '', ...extra } }];
const fixedReply = (r, extra = {}) => { remember(text, r.reply); return out({ action: 'reply', waMessage: r.waMessage, reply: r.reply, ...extra }); };

// Detección de datos dentro del mensaje.
const EMAIL = /[^\s@<>()]+@[^\s@<>()]+\.[a-z]{2,}/i;
const modalidadOf = (s) => {
  if (input.buttonId === 'cita_presencial') return 'presencial';
  if (input.buttonId === 'cita_virtual') return 'virtual';
  const p = /\b(presencial|presencialmente|oficina|en persona|ir al estudio)\b/.test(s);
  const v = /\b(virtual|virtualmente|videollamada|zoom|meet|en linea|online|remota|remoto|llamada)\b/.test(s);
  return p === v ? '' : (p ? 'presencial' : 'virtual');
};
const URGENT = /\b(urgente|urgencia|detenid[oa]|lo detuvieron|la detuvieron|me detuvieron|vence (hoy|manana)|plazo vence|audiencia (es )?(hoy|manana)|violencia|amenaza)/;
const HUMAN = /\b(hablar con (una persona|alguien|un abogado|una abogada|la doctora|el doctor|un humano)|asesor humano|persona real)\b/;
const ACKS = ['hola', 'ok', 'okay', 'si', 'no', 'gracias', 'muchas gracias', 'acepto', 'buenos dias', 'buenas tardes', 'buenas noches', 'buenas', 'listo', 'claro', 'de acuerdo', 'vale', 'ya', 'bien', 'perfecto'];
const BOOK = /\b(citas?|agendar|agendo|agendame|reservar|separar una|reunion|reunirme)\b|\b(quiero|quisiera|deseo|necesito|me gustaria)( tener| hacer| pedir| solicitar| sacar)?( una| un)? (consulta|asesoria)\b/;
const CANCEL = /^(cancelar|cancela|cancelo|ya no|olvidalo|olvidelo|mejor no|no quiero (la |una )?cita|anular)( la cita| la solicitud)?$/;
const INFO = /\b(cuanto cuesta|precio|costo|tarifa|donde (estan|quedan|queda)|direccion de (la|su) oficina)\b/;
const NO_EMAIL = /^(no|no gracias|sin correo|omitir|no tengo|no tengo correo|prefiero no|ninguno|no deseo|no por ahora|continuar sin correo|asi esta bien)$/;
const TIME_WORD = /\b(lunes|martes|miercoles|jueves|viernes|sabado|domingo|manana|tarde|hoy|semana|mediodia|am|pm|\d)/;

const parseName = (s) => {
  const v = s.replace(/^(hola[,.!\s]*)?(me llamo|mi nombre completo es|mi nombre es|soy|nombre:?)\s+/i, '').replace(/[.!]+$/, '').replace(/\s+/g, ' ').trim();
  const n = norm(v);
  if (!/^[\p{L}][\p{L}'’. -]{1,79}$/u.test(v) || v.split(' ').length > 6 || ACKS.includes(n) || BOOK.test(n)) return '';
  return v;
};

// Área según el tema (lista de servicios de system_prompt.md).
const AREAS = [
  [/matrimonio/, 'Actas de matrimonio'],
  [/alimento|pension/, 'Procesos de alimentos'],
  [/tenencia|custodia|regimen de visitas/, 'Tenencia'],
  [/herencia|sucesion|intestad|testamento|fallecio/, 'Sucesión intestada'],
  [/prescripcion|posesion/, 'Prescripción adquisitiva'],
  [/\blotes?\b|comprar (un )?terreno|proyecto/, 'Inmobiliario'],
  [/saneamiento|regulariz|predio|terreno|titulo|sunarp|inscri/, 'Saneamiento de predios'],
  [/rectific|partida|acta de nacimiento|acta de defuncion/, 'Rectificación de partida'],
  [/dano|afectacion|invasion/, 'Daños a la propiedad'],
  [/minuta/, 'Elaboración de minutas'],
  [/contrato/, 'Elaboración de contratos'],
  [/concilia/, 'Centro de conciliación'],
  [/carta notarial|notarial/, 'Cartas notariales'],
];
const areaOf = (s) => (AREAS.find(([re]) => re.test(norm(s))) || [null, 'Otro'])[1];
const short = (s, n) => (s.length > n ? `${s.slice(0, n - 1).trimEnd()}…` : s);

// Qué dato pidió el último mensaje del asistente (para tomar el relevo si lo pidió la IA).
const fieldAsked = (msg) => {
  const q = String(msg || '').split(/(?<=[.!\n])\s+/).filter((s) => s.includes('?')).pop() || '';
  const n = norm(q);
  if (!n) return '';
  // Solo preguntas inequívocas de una cita (el tema no: "¿en qué puedo ayudarle con su caso?" es general).
  if (/\b(su nombre|nombre completo)\b/.test(n)) return 'nombre';
  if (/\b(correo|e ?mail)\b/.test(n)) return 'correo';
  if (/\b(presencial|virtual)\b/.test(n)) return 'modalidad';
  if (/\b(dia|horario|hora|fecha)\b/.test(n) && /\b(acomod\w*|prefier\w*|cita)\b/.test(n)) return 'horario';
  return '';
};

// Toma del mensaje el dato pedido (y, de paso, correo, modalidad, urgencia o pedido de contacto humano).
// Devuelve 'ok', 'retry' (volver a preguntar) o 'llm' (es una duda: responde la IA).
const capture = (f, field) => {
  const email = (text.match(EMAIL) || [''])[0];
  const rest = email ? norm(text.replace(email, ' ')) : t;
  const onlyEmail = !!email && rest.replace(/\b(mi|correo|es|email|e mail|seria|el)\b/g, '').trim() === '';
  if (email && !f.datos.correo) { f.datos.correo = email.toLowerCase(); f.correoResuelto = true; }
  const mod = field === 'nombre' ? '' : modalidadOf(t);
  if (mod && !f.datos.modalidad) f.datos.modalidad = mod;
  if (URGENT.test(t)) f.urgente = true;
  if (HUMAN.test(t)) f.contactoHumano = true;
  const question = text.includes('?');

  if (field === 'nombre') {
    const v = parseName(text);
    if (v) { f.datos.nombre = v; return 'ok'; }
    return question ? 'llm' : 'retry';
  }
  if (field === 'tema') {
    if (onlyEmail || mod && rest.split(' ').length <= 2) return 'ok'; // dio otro dato; se vuelve a preguntar el tema
    if (ACKS.includes(t) || t.length < 3) return 'retry';
    // Una pregunta cuenta como tema solo si menciona un servicio ("¿Ven casos de herencia?"); si no
    // ("¿Atienden sábados?"), es una duda y responde la IA.
    if (INFO.test(t) || (question && areaOf(text) === 'Otro')) return 'llm';
    f.datos.tema = short(text, 300);
    return 'ok';
  }
  if (field === 'modalidad') {
    if (f.datos.modalidad) return 'ok';
    if (onlyEmail) return 'ok';
    return question ? 'llm' : 'retry';
  }
  if (field === 'horario') {
    if (onlyEmail || (mod && rest.split(' ').length <= 2)) return 'ok';
    if (ACKS.includes(t) || t.length < 2) return 'retry';
    if (question && !TIME_WORD.test(t)) return 'llm';
    f.datos.horario = short(text.replace(email, '').trim(), 120);
    return 'ok';
  }
  // correo (opcional)
  if (f.correoResuelto) return 'ok';
  if (input.buttonId === 'cita_sin_correo' || NO_EMAIL.test(t)) { f.correoResuelto = true; return 'ok'; }
  return question ? 'llm' : 'retry';
};

// Siguiente paso: pregunta el dato que falta o, si están todos, arma la cita.
const advance = (f, prefix) => {
  const next = missing(f);
  if (next) {
    f.asked = next;
    save(f);
    return fixedReply(ask(next, prefix));
  }
  const d = f.datos;
  const cita = {
    nombre: d.nombre,
    area: areaOf(d.tema),
    resumen: d.tema,
    tipo_cliente: /\b(empresa|mi negocio|compania|sac|eirl|s a)\b/.test(norm(d.tema)) ? 'empresa' : 'persona_natural',
    modalidad: d.modalidad,
    preferencia_horaria: d.horario,
    correo: d.correo,
    urgente: !!f.urgente,
    contacto_humano: !!f.contactoHumano,
    estado: 'completa',
  };
  f.asked = '';
  f.estado = 'guardando';
  save(f);
  const tema = short(d.tema, 80).replace(/^(\p{Lu})(?!\p{Lu})/u, (c) => c.toLowerCase());
  const summary = `Su *solicitud* de cita quedó registrada: ${d.nombre}, ${tema}, ${d.modalidad}, ${d.horario}${d.correo ? `, ${d.correo}` : ''}. El equipo del estudio le confirmará la fecha y hora por este medio en horario de atención.`;
  return fixedReply({ waMessage: textMessage(summary), reply: summary }, { citaToSave: cita, citaReplyFail: NOT_SAVED });
};

const toLLM = (f) => {
  const m = f && f.estado === 'en_curso' ? missing(f) : null;
  let citaLine = '';
  if (m) {
    citaLine = `Solicitud de cita: en curso (la gestiona el sistema; falta: ${LABELS[m]}). Responda solo la duda de la persona, sin pedir datos ni decir que la solicitud quedó registrada: el sistema volverá a preguntar el dato pendiente.`;
  } else if (f && f.estado === 'registrada') {
    citaLine = 'Solicitud de cita: registrada por el sistema. No pida de nuevo los datos.';
  }
  return out({ action: 'llm', citaLine, citaPending: m ? QUESTIONS[m] : '' });
};

let flow = live(store.citaFlow[from]);
if (!flow) delete store.citaFlow[from];

// Rechazo o revocación del consentimiento: se borran los datos de la cita (Ley N.° 29733).
if (input.consentEvent === 'rechazado') {
  delete store.citaFlow[from];
  return out({});
}
// Consentimiento recién otorgado: empieza la solicitud y se pregunta el primer dato que falta.
if (input.consentEvent === 'otorgado') {
  const f = start(flow);
  const next = missing(f);
  f.asked = next;
  save(f);
  const r = ask(next, ACCEPTED_PREFIX);
  replaceLastAssistant(input.reply, r.reply);
  return out({ waMessage: r.waMessage, reply: r.reply });
}
// Otras respuestas fijas de la puerta (consentimiento, /reiniciar, mensaje sin texto) o sin consentimiento.
if (input.action !== 'llm' || input.consentStatus !== 'otorgado') return out({});

if (flow && flow.estado === 'en_curso') {
  if (CANCEL.test(t)) {
    delete store.citaFlow[from];
    return fixedReply({ waMessage: textMessage(CANCELLED), reply: CANCELLED });
  }
  const field = flow.asked || missing(flow);
  const r = capture(flow, field);
  if (r === 'llm') { save(flow); return toLLM(flow); }
  if (r === 'retry' && !missing(flow)) return advance(flow, '');
  if (r === 'retry' && missing(flow) === field) { save(flow); return fixedReply(ask(field, RETRY)); }
  const filled = field === 'correo' ? flow.correoResuelto : !!flow.datos[field];
  return advance(flow, filled ? ACK[field] : '');
}

// Sin solicitud en curso: empieza si la persona pide una cita…
if (BOOK.test(t)) {
  const f = start(flow);
  const mod = modalidadOf(t);
  if (mod) f.datos.modalidad = mod;
  const email = (text.match(EMAIL) || [''])[0];
  if (email && !f.datos.correo) { f.datos.correo = email.toLowerCase(); f.correoResuelto = true; }
  if (URGENT.test(t)) f.urgente = true;
  if (HUMAN.test(t)) f.contactoHumano = true;
  return advance(f, 'Con gusto le ayudo con su solicitud de cita. ');
}
// …o toma el relevo si la IA acaba de pedir un dato de la cita y esta es la respuesta.
const lastAssistant = [...history()].reverse().find((m) => m.role === 'assistant');
const asked = lastAssistant && !(flow && flow.estado === 'registrada') ? fieldAsked(lastAssistant.content) : '';
if (asked) {
  const f = start(flow);
  const r = capture(f, asked);
  if (r === 'ok') return advance(f, ACK[asked] || '');
}

return toLLM(flow);
